import { get } from './app'
import { authorizeUrl, codeFrom, limitsOf, scopeIn, settingsOf } from './strava'
import { distanceText, hours, pace, readCache, slimActivities, weekStart, weeksOf } from './training'

// The bodies below are shaped as Strava documents them
// (developers.strava.com/docs/authentication and /docs/reference): the token
// exchange with its summary athlete, a refresh that hands out a new refresh
// token, SummaryActivity lists and ActivityStats, and Faults.
const EXCHANGED = {
  token_type: 'Bearer',
  // Six hours after the tests' NOW (10:00 local), in whatever zone they run.
  expires_at: Math.floor(new Date(2026, 10, 28, 16, 0, 0).getTime() / 1000),
  expires_in: 21600,
  refresh_token: 'e5n5675674b9f3c0a1d2e3f4a5b6c7d8e9f0a1b2',
  access_token: 'a4b945687g9c8d7e6f5a4b3c2d1e0f9a8b7c6d5e',
  athlete: {
    id: 4815162, username: 'samruns', resource_state: 2, firstname: 'Sam', lastname: 'Peeters', city: 'Ghent', state: 'Flanders',
    country: 'Belgium', sex: 'F', premium: true, summit: true, created_at: '2019-03-02T08:12:44Z', updated_at: '2026-11-20T18:01:09Z',
    profile_medium: 'https://dgalywyr863hv.cloudfront.net/pictures/athletes/4815162/medium.jpg',
    profile: 'https://dgalywyr863hv.cloudfront.net/pictures/athletes/4815162/large.jpg',
  },
}
const REFRESHED = {
  token_type: 'Bearer',
  access_token: 'a9b723f00e1d2c3b4a5f6e7d8c9b0a1f2e3d4c5b',
  // Six hours after the tests' NOW (10:00 local), in whatever zone they run.
  expires_at: Math.floor(new Date(2026, 10, 28, 16, 0, 0).getTime() / 1000),
  expires_in: 20566,
  refresh_token: 'b5c569aa0e1d2c3b4a5f6e7d8c9b0a1f2e3d4c5b',
}
const total = (count: number, distance: number, moving: number, climb: number) => ({
  count, distance, moving_time: moving, elapsed_time: Math.round(moving * 1.05), elevation_gain: climb, achievement_count: 0,
})
const STATS = {
  biggest_ride_distance: 112345.2,
  biggest_climb_elevation_gain: 812.4,
  recent_ride_totals: total(2, 76600.1, 10340, 625),
  recent_run_totals: total(12, 119300.5, 38400, 610.2),
  recent_swim_totals: total(0, 0, 0, 0),
  ytd_ride_totals: total(37, 1840200.4, 252000, 16300),
  ytd_run_totals: total(148, 1286400.5, 410220, 9840.2),
  ytd_swim_totals: total(0, 0, 0, 0),
  all_ride_totals: total(310, 15432000, 2100000, 140000),
  all_run_totals: total(1022, 9876543, 3150000, 67000),
  all_swim_totals: total(4, 6200, 9000, 0),
}

// Saturday 28 November 2026, 10:00 in the zone the test runs in.
const NOW = new Date(2026, 10, 28, 10, 0, 0).getTime()
function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// A SummaryActivity as Strava lists it, `days` before Saturday the 28th.
let nextId = 16000000000
function activity(days: number, name: string, sport: string, km: number, seconds: number, climb = 0) {
  const local = new Date(Date.UTC(2026, 10, 28 - days, 7, 30, 12))
  const utc = new Date(local.getTime() - 3600 * 1000)
  return {
    resource_state: 2,
    athlete: { id: 4815162, resource_state: 1 },
    name,
    distance: km * 1000 + 0.3,
    moving_time: seconds,
    elapsed_time: seconds + 95,
    total_elevation_gain: climb,
    type: sport === 'TrailRun' ? 'Run' : sport,
    sport_type: sport,
    workout_type: null,
    id: nextId++,
    start_date: utc.toISOString().replace(/\.\d+Z$/, 'Z'),
    start_date_local: local.toISOString().replace(/\.\d+Z$/, 'Z'),
    timezone: '(GMT+01:00) Europe/Brussels',
    utc_offset: 3600,
    achievement_count: 0,
    kudos_count: 4,
    comment_count: 0,
    athlete_count: 1,
    photo_count: 0,
    map: { id: 'a' + nextId, summary_polyline: 'ki{eFvqfiVqAWQIGEEKAYJgBVqDJ{BHa@jAkNJw@Pw@V{APs@^aABQAOEQGKoJ_FuJkFqAo@{A}@sH{DiAs@Q]?WVy@', resource_state: 2 },
    trainer: false,
    commute: false,
    manual: false,
    private: false,
    visibility: 'everyone',
    flagged: false,
    gear_id: 'g1234',
    average_speed: (km * 1000) / seconds,
    max_speed: 5.2,
    has_heartrate: false,
    elev_high: 20.1,
    elev_low: 2.4,
    pr_count: 0,
    total_photo_count: 0,
    has_kudoed: false,
  }
}
// Oldest first, as Strava answers a list asked with `after`.
const ACTIVITIES = [
  activity(20, 'Long run', 'Run', 18.4, 6020, 110),
  activity(12, 'Easy run', 'Run', 7.1, 2386, 22),
  activity(6, 'Sunday ride', 'Ride', 62.4, 8080, 540),
  activity(5, 'Morning Run', 'Run', 8.4, 2646, 48),
  activity(3, 'Tempo intervals', 'Run', 10.1, 2899, 64),
  activity(1, 'Easy shakeout', 'TrailRun', 6.2, 2096, 31),
]
const FAULT = (resource: string, field: string, code: string, message = 'Bad Request') => ({ message, errors: [{ resource, field, code }] })
const LIMITS = { 'x-ratelimit-limit': '200,2000', 'x-ratelimit-usage': '12,140', 'x-readratelimit-limit': '100,1000', 'x-readratelimit-usage': '9,120' }

const KEYS = { clientId: '184623', clientSecret: '0123456789abcdef0123456789abcdef01234567' }
const signedIn = (extra = {}) => ({
  ...KEYS,
  auth: {
    client: KEYS.clientId, access: 'old-access', expires: NOW + 5 * 3600 * 1000, refresh: 'old-refresh',
    athlete: { id: 4815162, name: 'Sam' }, code: 'c0de', at: 1,
  },
  ...extra,
})
const form = (body: string) => {
  const out: Record<string, string> = {}
  for (const part of String(body || '').split('&')) {
    const [k, v] = part.split('=')
    out[decodeURIComponent(k)] = decodeURIComponent(v || '')
  }
  return out
}
function textOf(node: any): string {
  if (node === null || node === undefined || node === false || node === true) return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(textOf).join(' ')
  return textOf(node.props?.children)
}

// A Strava that answers the token endpoint and the API as asked.
function strava(answers: { token?: (f: any) => any; activities?: (url: string) => any; stats?: any; athlete?: any } = {}) {
  return mock.httpRequest((url: string, options: any) => {
    if (url === 'https://www.strava.com/oauth/token') return answers.token ? answers.token(form(options.body)) : mock.json(REFRESHED)
    if (url.includes('/athlete/activities')) {
      if (answers.activities) return answers.activities(url)
      return { status: 200, headers: LIMITS, body: JSON.stringify(url.includes('page=1') ? ACTIVITIES : []) }
    }
    if (url.includes('/stats')) return answers.stats || { status: 200, headers: LIMITS, body: JSON.stringify(STATS) }
    if (url.endsWith('/athlete')) return answers.athlete || mock.json({ ...EXCHANGED.athlete, measurement_preference: 'feet' })
    return mock.response(404, FAULT('Resource', 'path', 'invalid', 'Resource Not Found'))
  })
}
const tokenCalls = (http: any) => http.calls.filter(([url]) => url === 'https://www.strava.com/oauth/token')

describe('the sign-in', () => {
  it('links to Strava with read and activity:read and the localhost redirect', () => {
    const link = authorizeUrl(settingsOf(makeApp({ state: KEYS })))
    expect(link).toBe(
      'https://www.strava.com/oauth/authorize?client_id=184623&redirect_uri=http%3A%2F%2Flocalhost%2Fexchange_token&response_type=code&approval_prompt=force&scope=read%2Cactivity%3Aread',
    )
  })

  it('finds the code and the scopes in the landed address', () => {
    const landed = 'http://localhost/exchange_token?state=&code=8f2c1e0b9a8d7c6b5a4f3e2d1c0b9a8f7e6d5c4b&scope=read,activity:read'
    expect(codeFrom(landed)).toBe('8f2c1e0b9a8d7c6b5a4f3e2d1c0b9a8f7e6d5c4b')
    expect(scopeIn(landed)).toBe('read,activity:read')
    expect(codeFrom('8f2c1e0b9a8d7c6b5a4f3e2d1c0b9a8f7e6d5c4b')).toBe('8f2c1e0b9a8d7c6b5a4f3e2d1c0b9a8f7e6d5c4b')
    expect(codeFrom('http://localhost/exchange_token?state=&error=access_denied')).toBe('')
  })

  it('trades a pasted address for a refresh token and the athlete, once', () => {
    const http = strava({ token: () => mock.json(EXCHANGED) })
    const app = makeApp({ state: { ...KEYS, signIn: 'http://localhost/exchange_token?state=&code=8f2c1e0b9a8d7c6b5a4f&scope=read,activity:read' } })
    at(NOW, () => get(app, makeContext()))
    expect(form(tokenCalls(http)[0][1].body)).toEqual({
      client_id: '184623', client_secret: KEYS.clientSecret, code: '8f2c1e0b9a8d7c6b5a4f', grant_type: 'authorization_code',
    })
    expect(app.state.signIn).toBe('')
    expect(app.state.auth).toMatchObject({
      refresh: EXCHANGED.refresh_token, access: EXCHANGED.access_token, expires: EXCHANGED.expires_at * 1000,
      athlete: { id: 4815162, name: 'Sam' }, code: '8f2c1e0b9a8d7c6b5a4f',
    })
    // The athlete's id from the sign-in: no GET /athlete.
    expect(http.calls.some(([url]) => url.endsWith('/api/v3/athlete'))).toBe(false)
    expect(http.calls.some(([url]) => url === 'https://www.strava.com/api/v3/athletes/4815162/stats')).toBe(true)
    app.state.signIn = 'http://localhost/exchange_token?state=&code=8f2c1e0b9a8d7c6b5a4f&scope=read,activity:read'
    at(NOW + 1000, () => get(app, makeContext()))
    expect(tokenCalls(http).length).toBe(1)
  })

  it('says so when "View data about your activities" was unticked', () => {
    const http = strava({ token: () => mock.json(EXCHANGED) })
    const app = makeApp({ state: { ...KEYS, signIn: 'http://localhost/exchange_token?state=&code=8f2c1e0b9a8d7c6b5a4f&scope=read' } })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Sign in to Strava')
    expect(screen).toContain('not allowed to see your activities')
    expect(http.calls.length).toBe(0)
  })

  it('always keeps the newest refresh token Strava hands out', () => {
    const http = strava()
    const app = makeApp({ state: signedIn({ auth: { ...signedIn().auth, expires: NOW + 60 * 1000 } }) })
    at(NOW, () => get(app, makeContext()))
    expect(form(tokenCalls(http)[0][1].body)).toEqual({
      client_id: '184623', client_secret: KEYS.clientSecret, grant_type: 'refresh_token', refresh_token: 'old-refresh',
    })
    expect(app.state.auth).toMatchObject({ refresh: REFRESHED.refresh_token, access: REFRESHED.access_token, athlete: { id: 4815162 } })
    // The next refresh, six hours on, sends the new one: the old one stopped working.
    at(REFRESHED.expires_at * 1000 - 60 * 1000, () => get(app, makeContext()))
    expect(form(tokenCalls(http)[1][1].body).refresh_token).toBe(REFRESHED.refresh_token)
    // A refresh that sends none keeps the one it has.
    mock.httpRequest((url) => (url.includes('oauth') ? mock.json({ ...REFRESHED, refresh_token: undefined, expires_at: 0 }) : mock.json([])))
    at(REFRESHED.expires_at * 1000 + 3600 * 1000, () => get(app, makeContext()))
    expect(app.state.auth.refresh).toBe(REFRESHED.refresh_token)
  })

  it('shows the sign-in again when Strava ended it, and keeps the last read', () => {
    strava({ token: () => mock.response(400, FAULT('RefreshToken', 'refresh_token', 'invalid')) })
    const cache = { at: NOW - 3600 * 1000, full: NOW, statsAt: NOW, athlete: { id: 4815162, name: 'Sam' }, year: 2026, ytd: {}, acts: [], sign: 'c0de' }
    const app = makeApp({ state: signedIn({ auth: { ...signedIn().auth, expires: NOW - 1000 }, cache }) })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Sign in to Strava')
    expect(screen).toContain('Strava ended this sign-in')
    expect(app.state.auth.refresh).toBeUndefined()
    expect(app.state.cache.at).toBe(NOW - 3600 * 1000)
  })

  it('says when the Client ID or Secret is wrong', () => {
    strava({ token: () => mock.response(401, FAULT('Application', 'client_secret', 'invalid')) })
    const app = makeApp({ state: signedIn({ auth: { ...signedIn().auth, expires: NOW - 1000 } }) })
    expect(textOf(at(NOW, () => get(app, makeContext())))).toContain('does not know this Client ID')
  })

  it('refreshes once on a 401 and asks again', () => {
    let lists = 0
    const http = mock.httpRequest((url: string, options: any) => {
      if (url.includes('oauth/token')) return mock.json(REFRESHED)
      if (url.includes('/athlete/activities')) {
        lists++
        return options.headers.Authorization === 'Bearer old-access'
          ? mock.response(401, FAULT('Athlete', 'access_token', 'invalid', 'Authorization Error'))
          : mock.json(ACTIVITIES)
      }
      return mock.json(STATS)
    })
    const app = makeApp({ state: signedIn() })
    at(NOW, () => get(app, makeContext()))
    expect(lists).toBe(2)
    expect(tokenCalls(http).length).toBe(1)
    expect(readCache(app)!.acts.length).toBe(6)
  })

  it('says how to mend a sign-in that may not read activities', () => {
    strava({
      activities: () => mock.response(401, FAULT('AccessToken', 'activity:read_permission', 'missing', 'Authorization Error')),
    })
    const app = makeApp({ state: signedIn() })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('leave "View data about your activities" ticked')
  })
})

describe('reading', () => {
  it('reads eight weeks of activities and the year, keeping only what it draws', () => {
    const http = strava()
    const app = makeApp({ state: signedIn() })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    const list = http.calls.find(([url]) => url.includes('/athlete/activities'))
    // From the Sunday before the Monday eight weeks back, at local midnight.
    const after = Math.floor(new Date(2026, 9, 4).getTime() / 1000)
    expect(list[0]).toBe(`https://www.strava.com/api/v3/athlete/activities?after=${after}&per_page=100&page=1`)
    expect(list[1].headers.Authorization).toBe('Bearer old-access')
    const cache = readCache(app)!
    expect(cache.acts.length).toBe(6)
    expect(cache.acts[0]).toEqual({ id: ACTIVITIES[5].id, name: 'Easy shakeout', sport: 'TrailRun', u: Date.parse(ACTIVITIES[5].start_date) / 1000, day: '2026-11-27', d: 6200, t: 2096, e: 31 })
    expect(cache.ytd.run).toEqual({ count: 148, d: 1286400.5, t: 410220, e: 9840.2 })
    // This week (from Monday the 23rd): three runs, the ride left out.
    expect(screen).toContain('24.7')
    expect(screen).toContain('of 30 km')
    expect(screen).toContain('3 runs')
    expect(screen).toContain('5.3 km to go')
    expect(screen).toContain('1,286 km')
    expect(screen).toContain('Easy shakeout')
    expect(screen).not.toContain('Sunday ride')
  })

  it('asks only for what is new between full reads, and for the year only when something is', () => {
    const http = strava()
    const app = makeApp({ state: signedIn() })
    at(NOW, () => get(app, makeContext()))
    const calls = http.calls.length
    // Before the interval: nothing.
    at(NOW + 10 * 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(calls)
    // At the interval: the activities after the newest kept, and no stats when none came.
    at(NOW + 30 * 60 * 1000, () => get(app, makeContext()))
    const newest = Date.parse(ACTIVITIES[5].start_date) / 1000
    expect(http.calls[calls][0]).toContain(`after=${newest - 1}&`)
    expect(http.calls.length).toBe(calls + 1)
    // A new one: the year again.
    const fresh = activity(0, 'Saturday long run', 'Run', 21.1, 6960, 95)
    strava({ activities: () => mock.json([fresh]) })
    const http2 = frameos.httpRequest as any
    at(NOW + 60 * 60 * 1000, () => get(app, makeContext()))
    expect(http2.calls.some(([url]) => url.includes('/stats'))).toBe(true)
    expect(readCache(app)!.acts[0].name).toBe('Saturday long run')
    expect(readCache(app)!.acts.length).toBe(7)
  })

  it('reads page after page while pages come full, 30 at a time on an ESP32', () => {
    const many = Array.from({ length: 45 }, (_, i) => activity(1 + (i % 50), `Run ${i}`, 'Run', 5, 1500))
    const http = strava({
      activities: (url) => {
        const page = Number(/[?&]page=(\d+)/.exec(url)![1])
        return mock.json(many.slice((page - 1) * 30, page * 30))
      },
    })
    const app = makeApp({ state: signedIn(), frame: { embedded: true } })
    at(NOW, () => get(app, makeContext()))
    const pages = http.calls.filter(([url]) => url.includes('/athlete/activities')).map(([url]) => /per_page=(\d+)&page=(\d+)/.exec(url)!.slice(1).join('/'))
    expect(pages).toEqual(['30/1', '30/2'])
    expect(readCache(app)!.acts.length).toBe(45)
  })

  it('looks the athlete up when the sign-in did not say who it was', () => {
    const http = strava()
    const app = makeApp({ state: signedIn({ auth: { ...signedIn().auth, athlete: undefined } }) })
    at(NOW, () => get(app, makeContext()))
    expect(http.calls.some(([url]) => url === 'https://www.strava.com/api/v3/athlete')).toBe(true)
    expect(readCache(app)!.athlete).toEqual({ id: 4815162, name: 'Sam', units: 'feet' })
    // Its profile is in miles, and Units says "as in your profile".
    expect(textOf(at(NOW + 1000, () => get(app, makeContext())))).toContain('of 30 mi')
  })
})

describe('the limits', () => {
  it('waits for the next quarter hour when the 15-minute reads are used up', () => {
    const quarter = (Math.floor(NOW / 900000) + 1) * 900000 + 5000
    expect(limitsOf({ ...LIMITS, 'x-readratelimit-usage': '100,412' }, NOW)).toBe(quarter)
    expect(limitsOf({ ...LIMITS, 'x-ratelimit-usage': '45,2000' }, NOW)).toBe((Math.floor(NOW / 86400000) + 1) * 86400000 + 5000)
    expect(limitsOf(LIMITS, NOW)).toBe(0)
  })

  it('makes no call until a limit that ran out starts again, and says so over the last read', () => {
    const http = strava({
      activities: () => mock.response(429, FAULT('Application', 'rate limit', 'exceeded', 'Rate Limit Exceeded'), { headers: { ...LIMITS, 'x-readratelimit-usage': '101,500' } }),
    })
    const cache = { at: NOW - 3600 * 1000, full: NOW - 7 * 3600 * 1000, statsAt: 0, athlete: { id: 4815162, name: 'Sam' }, year: 2026, ytd: { run: { count: 1, d: 5000, t: 1500, e: 0 } }, acts: [], sign: 'c0de' }
    const app = makeApp({ state: signedIn({ cache }) })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('used up its requests for these 15 minutes')
    const quarter = (Math.floor(NOW / 900000) + 1) * 900000 + 5000
    expect(app.nextSleep).toBe((quarter - NOW) / 1000 + 1)
    const calls = http.calls.length
    at(NOW + 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(calls)
  })

  it('keeps the last read when the network is down, and tries again sooner', () => {
    mock.httpRequest(() => ({ status: 0, error: 'connection refused' }))
    const cache = { at: NOW - 3600 * 1000, full: NOW, statsAt: NOW, athlete: { id: 4815162, name: 'Sam' }, year: 2026, ytd: { run: { count: 1, d: 5000, t: 1500, e: 0 } }, acts: [], sign: 'c0de' }
    const app = makeApp({ state: signedIn({ cache }) })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Could not reach Strava')
    expect(app.state.cache.at).toBe(NOW - 3600 * 1000)
    expect(app.nextSleep).toBe(60)
  })
})

describe('the numbers', () => {
  const slim = (a: any) => slimActivities([a])[0]
  it('says pace for a run, speed for a ride, and per 100 for a swim', () => {
    expect(pace(slim(activity(1, 'r', 'Run', 10, 3000)), 'km')).toBe('5:00 /km')
    expect(pace(slim(activity(1, 'r', 'Run', 10, 3000)), 'mi')).toBe('8:03 /mi')
    expect(pace(slim(activity(1, 'r', 'GravelRide', 60, 7200)), 'km')).toBe('30.0 km/h')
    expect(pace(slim(activity(1, 'r', 'Ride', 60, 7200)), 'mi')).toBe('18.6 mph')
    expect(pace(slim(activity(1, 's', 'Swim', 1.5, 1800)), 'km')).toBe('2:00 /100m')
  })

  it('writes distances and times as they read', () => {
    expect(distanceText(24680, 'km')).toBe('24.7 km')
    expect(distanceText(1286400, 'km')).toBe('1,286 km')
    expect(distanceText(48280, 'mi', false, true)).toBe('30 mi')
    expect(distanceText(1500, 'km', true)).toBe('1,500 m')
    expect(distanceText(0, 'km')).toBe('0 km')
    expect(hours(7620)).toBe('2h 7m')
    expect(hours(252000)).toBe('70h')
    expect(hours(2096)).toBe('35m')
  })

  it('puts activities in their weeks, from Monday or from Sunday', () => {
    const acts = slimActivities(ACTIVITIES)
    const monday = weeksOf(acts, 'run', '2026-11-28', false)
    expect(monday.length).toBe(8)
    expect(monday[7]).toMatchObject({ count: 3, d: 24700 })
    expect(monday[6]).toMatchObject({ count: 1, d: 7100 })
    const sunday = weeksOf(acts, 'run', '2026-11-28', true)
    // From Sunday the 22nd: the Monday run moves into this week, still three.
    expect(sunday[7].count).toBe(3)
    expect(weekStart('2026-11-28', false) - weekStart('2026-11-28', true)).toBe(1)
    expect(weeksOf(acts, 'ride', '2026-11-28', false)[6]).toMatchObject({ count: 1, d: 62400 })
  })
})

