// @name Strava
// @background #f7f5f2
// @refresh 1800
// A week of training at a glance, from Strava: this week's distance and time
// against a weekly goal, the last eight weeks as bars, the year's totals and
// the last few activities, for one sport (running, cycling or swimming).
//
// The frame asks Strava every half hour (the scene's refresh interval), and
// only for what changed: the activities since the newest it has (every
// activity of the eight weeks every six hours, so an edit or a delete shows
// too) and the year's totals when something is new. That is a request or
// two a read, far inside the limits of a Strava app (100 every 15 minutes,
// 1,000 a day), which it reads off every answer and waits out. The last read
// is kept on the frame's disk and stays up through a lost network.
//
// strava.ts signs in and talks to Strava, training.ts keeps the activities
// and works out the weeks and the words, ui.tsx has the looks and the setup
// screens.
import { authorizeUrl, newRender, readAuth, session, settingsOf, slowDown, waitUntil } from './strava'
import type { Settings } from './strava'
import {
  METERS, NOUNS, TITLES, WEEKS, distance, distanceText, grouped, hours, isSport, pace, readCache, refresh, shortDate, sportOf,
  todayOf, weeksOf, whenText,
} from './training'
import type { Activity, Cache, Sport, Total, Units, Week } from './training'
import { Banner, BigButton, Icon, SetupScreen, clamp, sizesOf, themeOf } from './ui'
import type { Sizes, Theme } from './ui'

const readAgain = () => frameos.remember('force', true)

// ---------------------------------------------------------------- parts

type View = {
  t: Theme; z: Sizes; W: number; H: number; cache: Cache; problem: string; sport: Sport; units: Units
  goal: number; weeks: Week[]; recent: Activity[]; ytd: Total; ytdShort: boolean; small: boolean
}

const noun = (sport: Sport, count: number) => `${grouped(count)} ${NOUNS[sport][count === 1 ? 0 : 1]}`
const climb = (meters: number, units: Units) => (units === 'mi' ? `${grouped(Math.round(meters * 3.28084))} ft` : `${grouped(Math.round(meters))} m`)
const clockOf = (at: number) => {
  const d = new Date(at)
  return `${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}`
}
function weekRange(start: number) {
  const first = shortDate(start)
  const last = shortDate(start + 6)
  return first.split(' ')[0] === last.split(' ')[0] ? `${first} - ${last.split(' ')[1]}` : `${first} - ${last}`
}

function Header({ v, compact }: { v: View; compact?: boolean }) {
  const { t, z, sport, weeks, cache } = v
  return (
    <div className={`flex items-center gap-[${z.s(12)}px]`}>
      <div className={`w-[${z.s(compact ? 34 : 42)}px] h-[${z.s(compact ? 34 : 42)}px] shrink-0 rounded-full flex items-center justify-center ${t.badge}`}>
        <Icon name={sport} size={z.s(compact ? 20 : 26)} />
      </div>
      <div className="flex-1 min-w-0 flex flex-col">
        <span className={`text-[${z.s(compact ? 18 : 22)}px] font-bold leading-tight truncate`}>{TITLES[sport]}</span>
        <span className={`text-[${z.s(13)}px] ${t.muted} truncate`}>{`This week, ${weekRange(weeks[WEEKS - 1].start)}`}</span>
      </div>
      {compact ? null : <span className={`text-[${z.s(12)}px] ${t.muted}`}>{`Updated ${clockOf(cache.at)}`}</span>}
      <div className={`w-[${z.s(40)}px] h-[${z.s(40)}px] shrink-0 rounded-full flex items-center justify-center ${t.button}`} onClick={readAgain}>
        <Icon name="refresh" size={z.s(20)} />
      </div>
    </div>
  )
}

// This week: the distance, large, against the goal, with the time, how many
// and how far to go.
function WeekBlock({ v, big }: { v: View; big: number }) {
  const { t, z, sport, units, goal } = v
  const week = v.weeks[WEEKS - 1]
  const swim = sport === 'swim'
  const d = distance(week.d, units, swim)
  const share = goal ? clamp(week.d / goal, 0, 1) : 0
  const left = goal - week.d
  return (
    <div className={`flex flex-col gap-[${z.s(10)}px]`}>
      <div className={`flex items-end gap-[${z.s(8)}px]`}>
        <span className={`text-[${z.s(big)}px] font-bold leading-none`}>{d.value}</span>
        <span className={`text-[${z.s(big * 0.38)}px] pb-[${z.s(big * 0.06)}px] ${t.muted}`}>{d.unit}</span>
        <div className="flex-1" />
        {goal ? <span className={`text-[${z.s(15)}px] pb-[${z.s(big * 0.06)}px] ${t.muted}`}>{`of ${distanceText(goal, units, swim, true)}`}</span> : null}
      </div>
      {goal ? (
        <div className={`h-[${z.s(12)}px] rounded-full ${t.track}`}>
          <div className={`h-full w-[${Math.round(share * 1000) / 10}%] min-w-[${z.s(12)}px] rounded-full ${t.fill}`} />
        </div>
      ) : null}
      <div className={`flex items-center gap-[${z.s(14)}px] text-[${z.s(15)}px]`}>
        <span className="flex items-center gap-[4px]">
          <Icon name="clock" size={z.s(16)} />
          {hours(week.t)}
        </span>
        <span>{noun(sport, week.count)}</span>
        <div className="flex-1" />
        {goal ? (
          <span className={`font-bold ${t.accent}`}>{left > 0 ? `${distanceText(left, units, swim)} to go` : 'Goal reached'}</span>
        ) : week.e && !swim ? (
          <span className={t.muted}>{`${climb(week.e, units)} up`}</span>
        ) : null}
      </div>
    </div>
  )
}

// The last eight weeks, this one last and lit, with the goal as a line.
function Bars({ v, height, ends }: { v: View; height: number; ends?: boolean }) {
  const { t, z, weeks, goal } = v
  const most = Math.max(goal, ...weeks.map((week) => week.d)) || 1
  const h = Math.max(20, height)
  const gap = z.s(6)
  return (
    <div className={`flex flex-col gap-[${z.s(4)}px]`}>
      <div className={`relative h-[${h}px]`}>
        <div className={`flex items-end h-full gap-[${gap}px]`}>
          {weeks.map((week, i) => (
            <div className={`flex-1 h-[${Math.max(z.s(3), Math.round((week.d / most) * h))}px] rounded-t-[${z.s(4)}px] ${i === WEEKS - 1 ? t.barNow : t.barOld}`} />
          ))}
        </div>
        {goal ? <div className={`absolute left-0 right-0 top-[${h - Math.round((goal / most) * h)}px] ${t.goal}`} /> : null}
      </div>
      {ends ? (
        <div className={`flex justify-between text-[${z.s(11)}px]`}>
          <span className={t.muted}>{shortDate(weeks[0].start)}</span>
          <span className="font-bold">{shortDate(weeks[WEEKS - 1].start)}</span>
        </div>
      ) : (
        <div className={`flex gap-[${gap}px]`}>
          {weeks.map((week, i) => (
            <span className={`flex-1 min-w-0 text-center text-[${z.s(11)}px] truncate ${i === WEEKS - 1 ? 'font-bold' : t.muted}`}>
              {shortDate(week.start)}
            </span>
          ))}
        </div>
      )}
    </div>
  )
}

// The year so far, as Strava counts it.
function YearBlock({ v, compact }: { v: View; compact?: boolean }) {
  const { t, z, sport, units, ytd, cache } = v
  const d = distance(ytd.d, units)
  return (
    <div className={`flex flex-col gap-[${z.s(4)}px] rounded-[${z.s(16)}px] p-[${z.s(compact ? 10 : 14)}px] ${t.card}`}>
      <span className={`text-[${z.s(13)}px] font-bold ${t.muted}`}>{`${cache.year} so far`}</span>
      <div className={`flex items-end flex-wrap gap-x-[${z.s(14)}px] gap-y-[${z.s(2)}px]`}>
        <span className={`text-[${z.s(compact ? 22 : 30)}px] font-bold leading-none`}>{`${d.value} ${d.unit}`}</span>
        <span className={`text-[${z.s(14)}px]`}>{noun(sport, ytd.count)}</span>
        <span className={`text-[${z.s(14)}px]`}>{hours(ytd.t)}</span>
        {sport !== 'swim' && ytd.e ? <span className={`text-[${z.s(14)}px]`}>{`${climb(ytd.e, units)} up`}</span> : null}
      </div>
      {v.ytdShort && !compact ? (
        <span className={`text-[${z.s(11)}px] ${t.muted}`}>Strava's totals count only activities everyone can see.</span>
      ) : null}
    </div>
  )
}

function RecentRow({ v, act, today }: { v: View; act: Activity; today: string }) {
  const { t, z, units, sport } = v
  return (
    <div className={`flex items-center gap-[${z.s(10)}px] py-[${z.s(7)}px] pr-[${z.s(10)}px] ${t.line}`}>
      <div className="flex-1 min-w-0 flex flex-col">
        <span className={`text-[${z.s(15)}px] font-bold truncate`}>{act.name || TITLES[sport]}</span>
        <span className={`text-[${z.s(12)}px] ${t.muted} truncate`}>{`${whenText(act.day, today)}, ${hours(act.t)}`}</span>
      </div>
      <div className="flex flex-col items-end shrink-0">
        <span className={`text-[${z.s(15)}px] font-bold`}>{distanceText(act.d, units, act.sport === 'Swim')}</span>
        <span className={`text-[${z.s(12)}px] ${t.muted}`}>{pace(act, units)}</span>
      </div>
    </div>
  )
}

function Recent({ v, today, whole }: { v: View; today: string; whole?: boolean }) {
  const { t, z, sport } = v
  return (
    <div className={`${whole ? '' : 'flex-1 min-h-0 '}flex flex-col rounded-[${z.s(16)}px] px-[${z.s(whole ? 10 : 14)}px] pt-[${z.s(10)}px] ${t.card}`}>
      <span className={`text-[${z.s(13)}px] font-bold ${t.muted}`}>{`Recent ${NOUNS[sport][1]}`}</span>
      {v.recent.length ? (
        <div className={whole ? '' : 'flex-1 min-h-0 overflow-y-auto'}>
          <div className="flex flex-col">
            {v.recent.map((act) => <RecentRow v={v} act={act} today={today} />)}
          </div>
        </div>
      ) : (
        <span className={`py-[${z.s(12)}px] text-[${z.s(14)}px] ${t.muted}`}>{`No ${NOUNS[sport][1]} in the last ${WEEKS} weeks.`}</span>
      )}
    </div>
  )
}

// ---------------------------------------------------------------- the layouts

// A wide panel: this week and the weeks on the left, the year and the last
// activities on the right.
function wide(v: View, today: string) {
  const { t, z, H } = v
  const chart = Math.round(H * (H < 400 ? 0.2 : 0.34)) - (v.problem ? z.s(50) : 0)
  return (
    <div className={`flex flex-col w-full h-full gap-[${z.s(12)}px] p-[${z.s(16)}px] ${t.page}`}>
      <Header v={v} />
      {v.problem ? <Banner t={t} z={z} text={v.problem} /> : null}
      <div className={`flex-1 min-h-0 flex gap-[${z.s(12)}px]`}>
        <div className={`w-[54%] shrink-0 flex flex-col justify-between rounded-[${z.s(16)}px] p-[${z.s(16)}px] ${t.card}`}>
          <WeekBlock v={v} big={54} />
          <Bars v={v} height={chart} />
        </div>
        <div className={`flex-1 min-w-0 flex flex-col gap-[${z.s(12)}px]`}>
          <YearBlock v={v} />
          <Recent v={v} today={today} />
        </div>
      </div>
    </div>
  )
}

// A tall panel: the same, stacked. A small or square one (a 2.8" LCD, a
// 4.2" e-paper, a 4" square) scrolls under its header, a finger or the
// frame's keys away.
function tall(v: View, today: string) {
  const { t, z, H, small } = v
  const chart = Math.round(H * (small ? 0.15 : 0.17)) - (v.problem && !small ? z.s(50) : 0)
  if (small || H < z.s(640))
    return (
      <div className={`flex flex-col w-full h-full gap-[${z.s(8)}px] p-[${z.s(small ? 10 : 14)}px] ${t.page}`}>
        <Header v={v} compact={small} />
        <div className="flex-1 min-h-0 overflow-y-auto">
          <div className={`flex flex-col gap-[${z.s(8)}px]`}>
            {v.problem ? <Banner t={t} z={z} text={v.problem} /> : null}
            <div className={`flex flex-col gap-[${z.s(12)}px] rounded-[${z.s(16)}px] p-[${z.s(small ? 10 : 14)}px] ${t.card}`}>
              <WeekBlock v={v} big={small ? 44 : 54} />
              <Bars v={v} height={Math.max(z.s(48), chart)} ends={small} />
            </div>
            <YearBlock v={v} compact={small} />
            <Recent v={v} today={today} whole />
          </div>
        </div>
      </div>
    )
  return (
    <div className={`flex flex-col w-full h-full gap-[${z.s(small ? 8 : 12)}px] p-[${z.s(small ? 10 : 16)}px] ${t.page}`}>
      <Header v={v} compact={small} />
      {v.problem ? <Banner t={t} z={z} text={v.problem} /> : null}
      <div className={`flex flex-col gap-[${z.s(14)}px] rounded-[${z.s(16)}px] p-[${z.s(small ? 10 : 16)}px] ${t.card}`}>
        <WeekBlock v={v} big={small ? 44 : 54} />
        <Bars v={v} height={chart} ends={small} />
      </div>
      <YearBlock v={v} compact={small} />
      <Recent v={v} today={today} />
    </div>
  )
}

// A round panel: the week's share of the goal as a ring along the rim, the
// distance in the middle, the weeks as bars under it, the last activity and
// the year in the arc at the bottom.
function round(v: View, today: string) {
  const { t, z, W, H, sport, units, goal } = v
  const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, (R - 14) ** 2 - dy * dy)))
  const week = v.weeks[WEEKS - 1]
  const swim = sport === 'swim'
  const d = distance(week.d, units, swim)
  const share = goal ? clamp(week.d / goal, 0, 1) : 0
  const rr = R - 8
  const a = share * 2 * Math.PI
  const arc = share >= 1
    ? `M ${cx} ${cy - rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy + rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy - rr}`
    : `M ${cx} ${cy - rr} A ${rr} ${rr} 0 ${share > 0.5 ? 1 : 0} 1 ${(cx + rr * Math.sin(a)).toFixed(1)} ${(cy - rr * Math.cos(a)).toFixed(1)}`
  const top = Math.round(R * 0.66)
  const barsTop = Math.round(R * 0.14)
  const barsH = Math.round(R * 0.3)
  const barsW = Math.round(chord(barsTop + barsH) * 0.86)
  const lineAt = (dy: number) => {
    const w = chord(dy + 18)
    return `absolute left-[${Math.round(cx - w / 2)}px] top-[${Math.round(cy + dy)}px] w-[${w}px] flex justify-center`
  }
  const last = v.recent[0]
  const ytd = distance(v.ytd.d, units)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <svg className={`absolute left-0 top-0 w-[${W}px] h-[${H}px]`} viewBox={`0 0 ${W} ${H}`} fill="none" strokeWidth={10} strokeLinecap="round">
        <circle cx={cx} cy={cy} r={rr} stroke={t.ringTrack} />
        {t.high ? <circle cx={cx} cy={cy} r={rr} stroke="#000000" strokeWidth={2} /> : null}
        {share > 0 ? <path d={arc} stroke={t.ring} /> : null}
      </svg>
      <div className={`absolute left-[${Math.round(cx - chord(top) / 2)}px] top-[${Math.round(cy - top)}px] w-[${chord(top)}px] flex flex-col items-center gap-[${z.s(4)}px]`}>
        <div className={`flex items-center gap-[${z.s(6)}px] text-[${z.s(15)}px] ${t.muted}`}>
          <Icon name={sport} size={z.s(18)} />
          <span>This week</span>
        </div>
        <div className={`flex items-end gap-[${z.s(6)}px]`}>
          <span className={`text-[${z.s(64)}px] font-bold leading-none`}>{d.value}</span>
          <span className={`text-[${z.s(22)}px] pb-[${z.s(5)}px] ${t.muted}`}>{d.unit}</span>
        </div>
        <span className={`text-[${z.s(15)}px] ${goal && week.d >= goal ? `font-bold ${t.accent}` : t.muted}`}>
          {goal ? (week.d >= goal ? 'Goal reached' : `of ${distanceText(goal, units, swim, true)}`) : noun(sport, week.count)}
        </span>
        <span className={`text-[${z.s(15)}px]`}>{goal ? `${hours(week.t)}, ${noun(sport, week.count)}` : hours(week.t)}</span>
      </div>
      <div className={`absolute left-[${Math.round(cx - barsW / 2)}px] top-[${Math.round(cy + barsTop)}px] w-[${barsW}px] h-[${barsH}px] flex items-end gap-[${z.s(5)}px]`}>
        {v.weeks.map((w, i) => {
          const most = Math.max(goal, ...v.weeks.map((x) => x.d)) || 1
          return <div className={`flex-1 h-[${Math.max(3, Math.round((w.d / most) * barsH))}px] rounded-t-[3px] ${i === WEEKS - 1 ? t.barNow : t.barOld}`} />
        })}
      </div>
      {v.problem ? (
        <div className={`absolute left-[${Math.round(cx - chord(R * 0.72) / 2)}px] top-[${Math.round(cy + R * 0.48)}px] w-[${chord(R * 0.72)}px]`}>
          <Banner t={t} z={z} text={v.problem} />
        </div>
      ) : last ? (
        <div className={lineAt(Math.round(R * 0.5))}>
          <span className={`text-[${z.s(13)}px] truncate`}>
            {`${whenText(last.day, today)}: ${distanceText(last.d, units, swim)}, ${pace(last, units)}`}
          </span>
        </div>
      ) : null}
      {v.problem ? null : (
        <div className={lineAt(Math.round(R * 0.5) + z.s(20))}>
          <span className={`text-[${z.s(13)}px] ${t.muted} truncate`}>{`${v.cache.year}: ${ytd.value} ${ytd.unit}, ${noun(sport, v.ytd.count)}`}</span>
        </div>
      )}
    </div>
  )
}

// ---------------------------------------------------------------- the screens before the dashboard

type Fit = { tight?: boolean; round?: { W: number; H: number } }

function setupScreen(t: Theme, z: Sizes, fit: Fit) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="run" title="Connect Strava"
      intro="This dashboard reads your training through a Strava API app of your own. It takes a few minutes, once."
      steps={[
        {
          head: 'Make a Strava API app',
          text: 'On strava.com/settings/api, create an app: any name, category and website, and this Authorization Callback Domain:',
          code: 'localhost',
        },
        {
          head: 'Copy its keys into this scene',
          text: "Copy the app's Client ID and Client Secret into this scene's settings, and save.",
        },
        {
          head: 'Sign in',
          text: 'Then this screen turns into a Sign in button.',
        },
      ]}
      note="Strava asks for a subscription to make an API app. A new app lets only its owner sign in, which is all this frame needs." />
  )
}

function signInScreen(t: Theme, z: Sizes, fit: Fit, s: Settings, problem: string) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="key" title="Sign in to Strava" problem={problem}
      intro="Let this frame read your activities."
      steps={[
        {
          head: 'Tap Sign in',
          text: "Scan its QR code with your phone (the editor's preview opens a tab instead), log in to Strava and press Authorize, with \"View data about your activities\" ticked.",
        },
        {
          head: 'Copy the address',
          text: 'The browser then fails to open a page. That is expected: copy its whole address, which starts with',
          code: `${s.redirectUri}?`,
        },
        {
          head: 'Paste it into Sign-in address',
          text: "In this scene's settings, and save. The frame signs in with it and stays signed in.",
        },
      ]}
      action={<BigButton t={t} z={z} icon="link" label="Sign in" href={authorizeUrl(s)} />} />
  )
}

function troubleScreen(t: Theme, z: Sizes, fit: Fit, problem: string) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="alert" title="No training yet" problem={problem}
      intro="" steps={[{ head: 'The frame tries again', text: 'On its own in a minute or two, or now with Try again.' }]}
      action={<BigButton t={t} z={z} icon="refresh" label="Try again" onClick={readAgain} />} />
  )
}

// ---------------------------------------------------------------- the scene

const ZERO: Total = { count: 0, d: 0, t: 0, e: 0 }

export function get(app, context) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const isRound = context?.round === true
  const t = themeOf(app)
  const now = Date.now()
  const z = sizesOf(W, H)
  // A tall panel sets the setup screens a little larger: its height has the room.
  const zSetup = !isRound && H >= W * 1.25 && z.k === 1 ? sizesOf(W, H, Math.min(1.3, W / 400, H / 640)) : z
  const fit: Fit = isRound ? { round: { W, H } } : { tight: H < 400 }
  const interval = Math.max(300, Number(app.state.refreshInterval) || 1800)

  newRender()
  const s = settingsOf(app)
  // Nothing changes on these screens until the settings do (a save renders).
  if (!s.clientId || !s.clientSecret) {
    frameos.setNextSleep(3600)
    return setupScreen(t, zSetup, fit)
  }
  const current = session(app, s)
  if (!current.signedIn) {
    frameos.setNextSleep(3600)
    return signInScreen(t, zSetup, fit, s, current.problem)
  }
  const client = current.token ? { app, s, token: current.token } : null
  const auth = readAuth(app)
  const sunday = app.state.weekStart === 'sunday'

  // The last good read, unless it was for another sign-in.
  let cache = readCache(app)
  if (cache && cache.sign !== auth.code) cache = null
  let problem = ''

  // Read when it is due (the scene's interval) or asked for, and not while
  // Strava's limits are used up. A failure keeps the last good read.
  const force = !!frameos.recall('force')
  const due = !cache || now - cache.at >= interval * 1000 - 30000 || force
  let failed = false
  if (force) frameos.remember('force', null)
  if (client && due && waitUntil() <= now) {
    const read = refresh(client, cache, auth.athlete || cache?.athlete, sunday)
    if (read.cache && read.cache !== cache) {
      read.cache.sign = auth.code
      cache = read.cache
      frameos.setState('cache', cache as any)
    }
    problem = read.problem
    failed = !!problem
    frameos.remember('problem', problem)
    frameos.remember('fails', failed ? Number(frameos.recall('fails') || 0) + 1 : 0)
    // The sign-in ended during that read: a 401 the refresh could not mend.
    const after = readAuth(app)
    if (!after.refresh) return signInScreen(t, zSetup, fit, s, after.error || '')
  } else {
    problem = String(frameos.recall('problem') || '')
    if (!client && current.problem) problem = current.problem
    if (!problem && due && waitUntil() > now) problem = slowDown(waitUntil(), now)
    failed = !!problem
  }

  // When to look again: the scene's interval, sooner after a failure (one,
  // two, four, eight, sixteen minutes), and not before Strava's limits start
  // again.
  const wait = waitUntil()
  if (wait > now) frameos.setNextSleep(Math.min(interval, Math.max(60, (wait - now) / 1000 + 1)))
  else if (failed) frameos.setNextSleep(Math.min(interval, 60 * 2 ** Math.min(4, Math.max(0, Number(frameos.recall('fails') || 1) - 1))))

  if (!cache) return troubleScreen(t, z, fit, problem || 'Reading your training...')

  const sport = sportOf(app.state.sport)
  const units: Units = app.state.units === 'mi' || app.state.units === 'km' ? app.state.units : cache.athlete?.units === 'feet' ? 'mi' : 'km'
  const today = todayOf(now)
  const year = new Date(now).getFullYear()
  const ytd = cache.year === year ? cache.ytd[sport] || ZERO : ZERO
  const mine = cache.acts.filter((act) => isSport(act, sport))
  const v: View = {
    t, z, W, H, cache, problem, sport, units,
    goal: Math.max(0, Number(app.state.goal ?? 30) || 0) * METERS[units],
    weeks: weeksOf(cache.acts, sport, today, sunday),
    recent: mine.slice(0, 6),
    ytd,
    // Strava's totals count public activities only: say so when the year
    // holds more of the sport than it counted.
    ytdShort: mine.filter((act) => act.day.slice(0, 4) === String(year)).length > ytd.count,
    small: z.small || H < 400,
  }
  if (isRound) return round(v, today)
  if (W >= H * 1.3 && W >= 640) return wide(v, today)
  return tall(v, today)
}

sources.strava.ts:
// Talking to Strava: the sign-in and the API calls the scene makes.
//
// The sign-in is the person's own API application (strava.com/settings/api):
// its Client ID and Client Secret are in the scene's settings, and the
// address Strava sends the browser to after "Authorize" is pasted back into
// the Sign-in address setting. Its code is traded here for a refresh token,
// kept in the scene's private `auth` state (on the frame's disk, never shown
// in its settings), and an access token is made from it whenever the last
// one is about to run out (six hours each). Strava hands out a NEW refresh
// token with a refresh, and the old one stops working at once: the newest is
// always the one kept. Nothing goes through a FrameOS server.

export const OAUTH = 'https://www.strava.com/oauth'
export const API = 'https://www.strava.com/api/v3'

// Read the profile, and the activities everyone or followers can see.
export const SCOPE = 'read,activity:read'

// Strava lets an application send the browser to localhost, whatever its
// Authorization Callback Domain says.
export const DEFAULT_REDIRECT = 'http://localhost/exchange_token'

export type Settings = { clientId: string; clientSecret: string; redirectUri: string; signIn: string }

export function settingsOf(app): Settings {
  const text = (key: string) => String(app.state[key] ?? '').trim()
  return {
    clientId: text('clientId'),
    clientSecret: text('clientSecret'),
    redirectUri: text('redirectUri') || DEFAULT_REDIRECT,
    signIn: text('signIn'),
  }
}

export const query = (values: Record<string, string>) =>
  Object.keys(values).map((key) => `${key}=${encodeURIComponent(values[key])}`).join('&')

// The page that asks the person to let the frame in. It holds no secret and
// no state of the frame's, so the same link works wherever it is opened: the
// frame's QR code, or the editor's preview, which opens it in a tab.
export function authorizeUrl(s: Settings) {
  return `${OAUTH}/authorize?${query({
    client_id: s.clientId,
    redirect_uri: s.redirectUri,
    response_type: 'code',
    approval_prompt: 'force',
    scope: SCOPE,
  })}`
}

const decoded = (text: string) => {
  try {
    return decodeURIComponent(text)
  } catch (e) {
    return text
  }
}

// The code in what was pasted: the whole address the browser ended on
// (http://localhost/exchange_token?state=&code=...&scope=read,activity:read),
// or the code alone.
export function codeFrom(text: string) {
  const found = /[?&#]code=([^&#\s]+)/.exec(text)
  if (found) return decoded(found[1])
  return /^[0-9a-f]{30,}$/i.test(text) ? text : ''
}

// The scopes the person left ticked on Strava's page, '' when it does not say.
export function scopeIn(text: string) {
  const found = /[?&#]scope=([^&#\s]*)/.exec(text)
  return found ? decoded(found[1]) : ''
}
const deniedIn = (text: string) => /[?&#]error=access_denied/.test(text)

// ---------------------------------------------------------------- the sign-in

// Whose activities: the athlete the sign-in was for, and the units their
// profile uses (Strava sends the athlete with the first token).
export type Athlete = { id: number; name: string; units?: string }

// What the scene keeps on the frame's disk. `client` is the Client ID it was
// made with (another one signs out), `code` the last pasted code (a code
// works once: the same one pasted again, or pushed again by the control
// plane, is not traded twice), `at` when it was written.
export type Auth = {
  client?: string
  access?: string
  expires?: number
  refresh?: string
  athlete?: Athlete
  code?: string
  error?: string
  at?: number
}

// The newest auth this render wrote: frameos.setState shows in app.state by
// the next render. get() forgets it as it starts (newRender), when app.state
// has it.
let written: Auth | null = null
export function newRender() {
  written = null
}

export function readAuth(app): Auth {
  let saved = app.state.auth
  if (typeof saved === 'string') {
    try {
      saved = saved ? JSON.parse(saved) : {}
    } catch (e) {
      saved = {}
    }
  }
  const stored: Auth = saved && typeof saved === 'object' ? saved : {}
  return written && (written.at || 0) >= (stored.at || 0) ? written : stored
}

export function writeAuth(auth: Auth) {
  auth.at = Date.now()
  written = auth
  frameos.setState('auth', auth as any)
}

type TokenReply = { ok: boolean; data?: any; error?: string; kind?: string; status?: number }

// What Strava says went wrong: its first error's resource, field and code.
function faultOf(data: any) {
  const first = Array.isArray(data?.errors) ? data.errors[0] : null
  return {
    message: String(data?.message || ''),
    resource: String(first?.resource || ''),
    field: String(first?.field || ''),
    code: String(first?.code || ''),
  }
}

function tokenRequest(s: Settings, form: Record<string, string>): TokenReply {
  const reply = frameos.httpRequest(`${OAUTH}/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
    body: query({ client_id: s.clientId, client_secret: s.clientSecret, ...form }),
    timeoutMs: 10000,
  })
  if (!reply.status) return { ok: false, error: `Could not reach Strava: ${reply.error || 'no answer'}` }
  let data: any = null
  try {
    data = reply.body ? JSON.parse(reply.body) : null
  } catch (e) {
    data = null
  }
  if (reply.status === 200 && data && data.access_token) return { ok: true, data }
  const fault = faultOf(data)
  // The sign-in is over (a revoked or replaced refresh token, an unknown
  // client), or this one attempt failed (a used code, too many requests).
  const kind = fault.resource === 'Application' ? 'client' : fault.resource === 'RefreshToken' ? 'revoked' : reply.status === 429 ? 'busy' : 'other'
  return { ok: false, kind, status: reply.status, error: tokenProblem(fault, reply.status, form.grant_type) }
}

// What a refusal at the token endpoint means to a person.
function tokenProblem(fault: ReturnType<typeof faultOf>, status: number, grant: string) {
  if (fault.resource === 'Application')
    return 'Strava does not know this Client ID and Client Secret: copy both again from strava.com/settings/api.'
  if (fault.resource === 'RefreshToken' || (grant === 'refresh_token' && (status === 400 || status === 401)))
    return 'Strava ended this sign-in (it was revoked under Settings, My Apps, or the app was reset). Sign in again.'
  if (fault.resource === 'AuthorizationCode' || grant === 'authorization_code')
    return 'That sign-in address was used already or is too old (it works once). Sign in again and paste the new one.'
  if (status === 429) return 'Strava asks to wait a little before the next sign-in.'
  return `Strava refused the sign-in: ${fault.message || `HTTP ${status}`}`
}

function fromToken(s: Settings, data: any, old: Auth, code: string): Auth {
  const athlete = data.athlete && data.athlete.id
    ? {
        id: Number(data.athlete.id),
        name: String(data.athlete.firstname || ''),
        units: data.athlete.measurement_preference ? String(data.athlete.measurement_preference) : old.athlete?.units,
      }
    : old.athlete
  const expiresAt = Number(data.expires_at) * 1000
  return {
    client: s.clientId,
    access: String(data.access_token),
    expires: expiresAt > Date.now() ? expiresAt : Date.now() + Math.max(60, Number(data.expires_in) || 21600) * 1000,
    // Always the newest: Strava stops the old one when it sends a new one.
    refresh: String(data.refresh_token || old.refresh || ''),
    athlete,
    code,
  }
}

export type Session = {
  token: string
  // Signed in, perhaps with a problem for the moment: no network. Otherwise the
  // sign-in screen shows, with the problem when there is one.
  signedIn: boolean
  problem: string
}

// A new access token is asked for this long before the last runs out: a
// render may come late, and Strava gives a new one only in its last hour.
const EARLY_MS = 10 * 60 * 1000

// Trades a pasted address for a sign-in, and an old access token for a new
// one. `force` makes a new one even when the last has time left (after a 401).
export function session(app, s: Settings, force = false): Session {
  let auth = readAuth(app)
  if (auth.client && auth.client !== s.clientId) auth = { code: auth.code }

  const pasted = s.signIn
  const code = pasted ? codeFrom(pasted) : ''
  if (pasted && (!code || code !== auth.code)) {
    const granted = scopeIn(pasted)
    if (code && granted && !/activity:read/.test(granted)) {
      auth = { ...auth, code, error: 'The frame was not allowed to see your activities. Sign in again and leave "View data about your activities" ticked.' }
    } else if (code) {
      const reply = tokenRequest(s, { code, grant_type: 'authorization_code' })
      if (reply.ok) auth = fromToken(s, reply.data, {}, code)
      // A failed new sign-in keeps one that works.
      else if (reply.status) auth = { ...auth, code, error: reply.error }
      else return { token: '', signedIn: !!auth.refresh, problem: reply.error || '' }
    } else {
      auth = {
        ...auth,
        error: deniedIn(pasted)
          ? 'You did not let the frame in on Strava\'s page. Sign in again and press "Authorize".'
          : 'The Sign-in address has no code in it: paste the whole address the browser ended on after "Authorize".',
      }
    }
    writeAuth(auth)
    frameos.setState('signIn', '')
  }

  if (!auth.refresh) return { token: '', signedIn: false, problem: auth.error || '' }
  if (!force && auth.access && (auth.expires || 0) > Date.now() + EARLY_MS)
    return { token: auth.access, signedIn: true, problem: '' }

  const reply = tokenRequest(s, { grant_type: 'refresh_token', refresh_token: auth.refresh })
  if (reply.ok) {
    auth = fromToken(s, reply.data, auth, auth.code || '')
    writeAuth(auth)
    return { token: auth.access!, signedIn: true, problem: '' }
  }
  if (reply.kind === 'revoked' || reply.kind === 'client') {
    writeAuth({ client: s.clientId, code: auth.code, error: reply.error })
    return { token: '', signedIn: false, problem: reply.error || '' }
  }
  // No network, or Strava busy: the access token may still work a while.
  if (auth.access && (auth.expires || 0) > Date.now()) return { token: auth.access, signedIn: true, problem: '' }
  return { token: '', signedIn: true, problem: reply.error || 'Could not reach Strava' }
}

// ---------------------------------------------------------------- the API

export type Reply = { status: number; data?: any; error?: string }
export type Client = { app: any; s: Settings; token: string }

// Strava's limits are its application's, per 15 minutes (at :00, :15, :30
// and :45) and per day (from midnight UTC), and every answer says how much
// of them is used. When one is used up, no call is made until it starts
// again (frameos.remember, so it holds across renders and on a board that
// starts each render afresh).
export const waitUntil = () => Number(frameos.recall('wait') || 0)

const pair = (text: any) => String(text || '').split(',').map((part) => Number(part.trim()))
export function limitsOf(headers: Record<string, string> | undefined, now: number) {
  if (!headers) return 0
  let until = 0
  for (const [usage, limit] of [
    ['x-ratelimit-usage', 'x-ratelimit-limit'],
    ['x-readratelimit-usage', 'x-readratelimit-limit'],
  ]) {
    const used = pair(headers[usage])
    const most = pair(headers[limit])
    if (used.length < 2 || most.length < 2 || !most[0] || !most[1]) continue
    if (used[1] >= most[1]) until = Math.max(until, nextUtcMidnight(now))
    else if (used[0] >= most[0]) until = Math.max(until, nextQuarter(now))
  }
  return until
}
export const nextQuarter = (now: number) => (Math.floor(now / 900000) + 1) * 900000 + 5000
export const nextUtcMidnight = (now: number) => (Math.floor(now / 86400000) + 1) * 86400000 + 5000

export function slowDown(until: number, now: number) {
  const d = new Date(until)
  const at = `${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}`
  return until - now > 3600000
    ? `Your Strava app used up its requests for today: the frame asks again after ${at}.`
    : `Your Strava app used up its requests for these 15 minutes: the frame asks again at ${at}.`
}

export function call(client: Client, path: string, retried = false): Reply {
  const now = Date.now()
  const wait = waitUntil()
  if (wait > now) return { status: 429, error: slowDown(wait, now) }
  const reply = frameos.httpRequest(API + path, {
    method: 'GET',
    headers: { Authorization: `Bearer ${client.token}`, Accept: 'application/json' },
    timeoutMs: 15000,
  })
  if (!reply.status) return { status: 0, error: `Could not reach Strava: ${reply.error || 'no answer'}` }
  const until = limitsOf(reply.headers, Date.now()) || (reply.status === 429 ? nextQuarter(Date.now()) : 0)
  if (until) frameos.remember('wait', until)
  if (reply.status === 429) return { status: 429, error: slowDown(until, Date.now()) }
  if (reply.status === 401 && !retried) {
    const again = session(client.app, client.s, true)
    if (!again.token) return { status: 401, error: again.problem || 'Signed out of Strava' }
    client.token = again.token
    return call(client, path, true)
  }
  let data: any = null
  try {
    data = reply.body ? JSON.parse(reply.body) : null
  } catch (e) {
    data = null
  }
  if (reply.status >= 400) return { status: reply.status, error: apiProblem(reply.status, faultOf(data)) }
  return { status: reply.status, data }
}

function apiProblem(status: number, fault: ReturnType<typeof faultOf>) {
  if (/permission/.test(fault.field) || (status === 401 && fault.code === 'missing'))
    return 'This sign-in may not see your activities. Sign in again and leave "View data about your activities" ticked.'
  if (status === 401) return 'Strava did not take the sign-in. Sign in again.'
  if (status >= 500) return `Strava is having trouble (HTTP ${status}): the frame tries again soon.`
  return `Strava answered: ${fault.message || `HTTP ${status}`}`
}

sources.training.ts:
// The training on the frame: what is kept of it, how it is read from Strava,
// and the weeks, totals and words worked out from it.
//
// The last good read is scene state, kept on the frame's disk (the private
// `cache` field), so a frame that restarts without a network, or whose
// sign-in ran out, still shows it under the problem. Only what is drawn is
// kept: each activity of the last eight weeks as a few numbers and its name,
// and the year's totals per sport.
import { call } from './strava'
import type { Athlete, Client } from './strava'

// One activity: its id, name, sport (Strava's sport_type), when it started
// (`u` seconds since 1970; `day` the date where it was done), distance in
// meters, moving time in seconds, climb in meters.
export type Activity = { id: number; name: string; sport: string; u: number; day: string; d: number; t: number; e: number }
export type Total = { count: number; d: number; t: number; e: number }
export type Cache = {
  at: number
  // When every activity of the window was last read, and the stats.
  full: number
  statsAt: number
  athlete: Athlete
  year: number
  ytd: Record<string, Total>
  acts: Activity[]
  // The sign-in it was read with.
  sign?: string
}

export const WEEKS = 8
const FULL_EVERY_MS = 6 * 3600 * 1000
const STATS_EVERY_MS = 6 * 3600 * 1000
const KEEP = 200
const NAME_MAX = 80

export function readCache(app): Cache | null {
  let kept = app.state.cache
  if (typeof kept === 'string') {
    try {
      kept = kept ? JSON.parse(kept) : null
    } catch (e) {
      kept = null
    }
  }
  return kept && typeof kept === 'object' && Array.isArray(kept.acts) ? kept : null
}

// ---------------------------------------------------------------- sports

export type Sport = 'run' | 'ride' | 'swim'
// Strava's sport types, by the sport the scene shows.
const SPORTS: Record<Sport, string[]> = {
  run: ['Run', 'TrailRun', 'VirtualRun'],
  ride: ['Ride', 'MountainBikeRide', 'GravelRide', 'EBikeRide', 'EMountainBikeRide', 'VirtualRide', 'Velomobile', 'Handcycle'],
  swim: ['Swim'],
}
export const sportOf = (value: any): Sport => (value === 'ride' || value === 'swim' ? value : 'run')
export const isSport = (activity: Activity, sport: Sport) => SPORTS[sport].includes(activity.sport)
export const NOUNS: Record<Sport, [string, string]> = { run: ['run', 'runs'], ride: ['ride', 'rides'], swim: ['swim', 'swims'] }
export const TITLES: Record<Sport, string> = { run: 'Running', ride: 'Cycling', swim: 'Swimming' }

// ---------------------------------------------------------------- reading

// "2026-11-27T07:15:09Z" (Strava's start_date_local: the local time, though
// it says Z): the date as it was where the activity was done.
const dayOf = (text: any) => (typeof text === 'string' && /^\d{4}-\d{2}-\d{2}/.test(text) ? text.slice(0, 10) : '')

export function slimActivities(data: any): Activity[] {
  const items = Array.isArray(data) ? data : []
  return items
    .filter((item) => item && item.id && item.start_date)
    .map((item) => ({
      id: Number(item.id),
      name: String(item.name || '').slice(0, NAME_MAX),
      sport: String(item.sport_type || item.type || ''),
      u: Math.round(Date.parse(String(item.start_date)) / 1000) || 0,
      day: dayOf(item.start_date_local) || dayOf(item.start_date),
      d: Math.round(Number(item.distance) || 0),
      t: Math.round(Number(item.moving_time) || 0),
      e: Math.round(Number(item.total_elevation_gain) || 0),
    }))
}

const total = (stats: any): Total => ({
  count: Number(stats?.count) || 0,
  d: Number(stats?.distance) || 0,
  t: Number(stats?.moving_time) || 0,
  e: Number(stats?.elevation_gain) || 0,
})
export const slimStats = (data: any): Record<string, Total> => ({
  run: total(data?.ytd_run_totals),
  ride: total(data?.ytd_ride_totals),
  swim: total(data?.ytd_swim_totals),
})

// The first day of the week holding `day`, and of the window of weeks.
export const dayNumber = (day: string) => Math.round(Date.UTC(Number(day.slice(0, 4)), Number(day.slice(5, 7)) - 1, Number(day.slice(8, 10))) / 86400000)
export const dayText = (n: number) => new Date(n * 86400000).toISOString().slice(0, 10)
export function weekStart(day: string, sunday: boolean) {
  const n = dayNumber(day)
  const weekday = (n + 4) % 7 // 0 Sunday
  return n - (sunday ? weekday : (weekday + 6) % 7)
}
export function todayOf(now: number) {
  const d = new Date(now)
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}
// Local midnight of the window's first day, in seconds since 1970: Strava's `after`.
function windowAfter(now: number, sunday: boolean) {
  const first = weekStart(todayOf(now), sunday) - 7 * (WEEKS - 1) - 1
  const day = dayText(first)
  return Math.floor(new Date(Number(day.slice(0, 4)), Number(day.slice(5, 7)) - 1, Number(day.slice(8, 10))).getTime() / 1000)
}

export type Read = { cache: Cache | null; problem: string }

// Reads what changed since the last read: every activity of the window now
// and then (an edit or a delete shows then), else only the ones after the
// newest kept, and the year's totals when there is something new. A failure
// keeps what was kept and says why.
export function refresh(client: Client, kept: Cache | null, athlete: Athlete | undefined, sunday: boolean): Read {
  const now = Date.now()
  let who = athlete
  if (!who || !who.id) {
    const me = call(client, '/athlete')
    if (me.status !== 200) return { cache: kept, problem: me.error || `HTTP ${me.status}` }
    who = { id: Number(me.data?.id), name: String(me.data?.firstname || ''), units: me.data?.measurement_preference }
  }
  // A day more than the window, so a change of the first day of the week needs no new read.
  const after = windowAfter(now, sunday)
  const full = !kept || now - kept.full > FULL_EVERY_MS || kept.athlete?.id !== who.id
  const newest = !full && kept!.acts.length ? kept!.acts[0].u : 0
  const from = full ? after : Math.max(after, newest - 1)
  const perPage = client.app.frame?.embedded ? 30 : 100
  const pages = Math.ceil(KEEP / perPage)
  let found: Activity[] = []
  for (let page = 1; page <= pages; page++) {
    const reply = call(client, `/athlete/activities?after=${from}&per_page=${perPage}&page=${page}`)
    if (reply.status !== 200) return { cache: kept, problem: reply.error || `HTTP ${reply.status}` }
    const slim = slimActivities(reply.data)
    found = found.concat(slim)
    if (slim.length < perPage) break
  }
  const known: Record<string, boolean> = {}
  const acts = (full ? found : found.concat(kept!.acts))
    .filter((act) => (known[act.id] ? false : (known[act.id] = true)))
    .filter((act) => act.u >= after)
    .sort((a, b) => b.u - a.u)
    .slice(0, KEEP)
  const added = full || acts.some((act) => act.u > newest)
  const year = new Date(now).getFullYear()
  let ytd = kept?.ytd || null
  let statsAt = kept?.statsAt || 0
  if (!ytd || added || now - statsAt > STATS_EVERY_MS || kept?.year !== year) {
    const stats = call(client, `/athletes/${who.id}/stats`)
    if (stats.status === 200) {
      ytd = slimStats(stats.data)
      statsAt = now
    } else if (!ytd) {
      return { cache: kept, problem: stats.error || `HTTP ${stats.status}` }
    }
  }
  return {
    cache: { at: now, full: full ? now : kept!.full, statsAt, athlete: who, year, ytd: ytd!, acts },
    problem: '',
  }
}

// ---------------------------------------------------------------- the weeks

export type Week = { start: number; d: number; t: number; e: number; count: number }

// The last eight weeks of the sport, oldest first; the last is this week.
export function weeksOf(acts: Activity[], sport: Sport, today: string, sunday: boolean): Week[] {
  const thisWeek = weekStart(today, sunday)
  const weeks: Week[] = []
  for (let i = WEEKS - 1; i >= 0; i--) weeks.push({ start: thisWeek - 7 * i, d: 0, t: 0, e: 0, count: 0 })
  for (const act of acts) {
    if (!isSport(act, sport) || !act.day) continue
    const at = Math.floor((weekStart(act.day, sunday) - weeks[0].start) / 7)
    if (at < 0 || at >= WEEKS) continue
    weeks[at].d += act.d
    weeks[at].t += act.t
    weeks[at].e += act.e
    weeks[at].count++
  }
  return weeks
}

// ---------------------------------------------------------------- words

export type Units = 'km' | 'mi'
export const METERS: Record<Units, number> = { km: 1000, mi: 1609.344 }

// A distance: kilometers or miles with a decimal; a swim in meters or yards.
export function distance(meters: number, units: Units, swim = false): { value: string; unit: string } {
  if (swim) {
    const yards = units === 'mi'
    return { value: grouped(Math.round(yards ? meters / 0.9144 : meters)), unit: yards ? 'yd' : 'm' }
  }
  const n = meters / METERS[units]
  const value = n >= 1000 ? grouped(Math.round(n)) : n >= 100 ? String(Math.round(n)) : n > 0 ? n.toFixed(1) : '0'
  return { value, unit: units }
}
// `round`: a goal, whose 30.0 km is 30 km.
export const distanceText = (meters: number, units: Units, swim = false, round = false) => {
  const { value, unit } = distance(meters, units, swim)
  return `${round ? value.replace(/\.0$/, '') : value} ${unit}`
}
export const grouped = (n: number) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',')

// 42:10, 1:42:10.
export function clock(seconds: number) {
  const s = Math.max(0, Math.round(seconds))
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const rest = String(s % 60).padStart(2, '0')
  return h ? `${h}:${String(m).padStart(2, '0')}:${rest}` : `${m}:${rest}`
}
// 71h 20m, 45m.
export function hours(seconds: number) {
  const m = Math.round(Math.max(0, seconds) / 60)
  const h = Math.floor(m / 60)
  return h ? (m % 60 ? `${grouped(h)}h ${m % 60}m` : `${grouped(h)}h`) : `${m}m`
}

// How fast, as a runner, a rider or a swimmer says it: 5:01 /km, 27.4 km/h,
// 1:52 /100m.
export function pace(act: Activity, units: Units): string {
  if (!act.d || !act.t) return ''
  if (SPORTS.ride.includes(act.sport)) {
    const speed = act.d / METERS[units] / (act.t / 3600)
    return `${speed.toFixed(1)} ${units === 'mi' ? 'mph' : 'km/h'}`
  }
  if (act.sport === 'Swim') {
    const per = units === 'mi' ? 91.44 : 100
    return `${clock(act.t / (act.d / per))} /100${units === 'mi' ? 'yd' : 'm'}`
  }
  return `${clock(act.t / (act.d / METERS[units]))} /${units}`
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

// Nov 23 for a day number.
export const shortDate = (n: number) => {
  const day = dayText(n)
  return `${MONTHS[Number(day.slice(5, 7)) - 1]} ${Number(day.slice(8, 10))}`
}
// Today, Yesterday, a weekday within the week, else Nov 21.
export function whenText(day: string, today: string) {
  if (!day) return ''
  const ago = dayNumber(today) - dayNumber(day)
  if (ago === 0) return 'Today'
  if (ago === 1) return 'Yesterday'
  if (ago > 1 && ago < 7) return DAYS[(dayNumber(day) + 4) % 7]
  return shortDate(dayNumber(day))
}

