// The parts of the scene that know nothing of Strava: the looks, sizes worked
// out from the canvas, icons and the setup screens. app.tsx decides what
// shows; this file only draws.

// ---------------------------------------------------------------- looks

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
export const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  // Warm white, one orange for this week and what moves.
  color: {
    high: false,
    page: 'bg-[#f7f5f2] text-[#242428]',
    muted: 'text-[#6d6d78]',
    accent: 'text-[#fc5200]',
    card: 'bg-white',
    line: 'border-b border-[#eeebe7]',
    track: 'bg-[#efe9e3]',
    fill: 'bg-[#fc5200]',
    badge: 'bg-[#fc5200] text-white',
    button: 'text-[#4a4a55] active:bg-[#ece6df]',
    primary: 'bg-[#fc5200] text-white active:bg-[#d94600]',
    banner: 'bg-[#fde3d6] text-[#7a2600]',
    code: 'bg-[#f3eee9] text-[#c43f00]',
    step: 'bg-[#fc5200] text-white',
    // The bars of the weeks: this one, the ones before, the goal's line.
    barNow: 'bg-[#fc5200]',
    barOld: 'bg-[#f8b897]',
    goal: 'border-t-2 border-[#242428]',
    ring: '#fc5200',
    ringTrack: '#efe9e3',
  },
  // Black on white, borders for cards, black fills: no greys to dither on
  // e-paper.
  high: {
    high: true,
    page: 'bg-white text-black',
    muted: 'text-black',
    accent: 'text-black',
    card: 'bg-white border-2 border-black',
    line: 'border-b-2 border-black',
    track: 'bg-white border-2 border-black',
    fill: 'bg-black',
    badge: 'bg-black text-white',
    button: 'text-black',
    primary: 'bg-black text-white',
    banner: 'bg-black text-white',
    code: 'bg-white text-black border-2 border-black',
    step: 'bg-black text-white',
    barNow: 'bg-black',
    barOld: 'bg-white border-2 border-black',
    goal: 'border-t-2 border-black',
    ring: '#000000',
    ringTrack: '#ffffff',
  },
}
// Color e-paper (a Spectra's six inks): the high-contrast page with this
// week in the panel's own red, the nearest of its inks to Strava's orange,
// as the panel shows it, so nothing is dithered into confetti.
const INKS = {
  ...THEMES.high,
  accent: 'text-[#6b1119]',
  fill: 'bg-[#6b1119]',
  badge: 'bg-[#6b1119] text-white',
  primary: 'bg-[#6b1119] text-white',
  banner: 'bg-[#6b1119] text-white',
  code: 'bg-white text-[#6b1119] border-2 border-[#6b1119]',
  step: 'bg-[#6b1119] text-white',
  barNow: 'bg-[#6b1119]',
  barOld: 'bg-black',
  goal: 'border-t-4 border-[#6b1119]',
  ring: '#6b1119',
}
export type Theme = typeof THEMES.color
export const themeOf = (app): Theme => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return INKS
  return THEMES.color
}

// Every length comes from the canvas: drawn for about 480 px on the shorter
// side, smaller on a small screen (a 2.8" LCD, a watch), and on a panel of
// 900 px or more (a 13.3" color e-paper at render scale 1) that much larger,
// by halves, so the list fills it. s(16) is what 16 px is on this frame.
export function sizesOf(W: number, H: number, scale = 0) {
  const short = Math.min(W, H)
  const k = scale || (short >= 900 ? Math.min(3, Math.floor((short / 480) * 2) / 2) : short < 360 ? Math.max(0.75, short / 400) : 1)
  const s = (px: number) => Math.max(1, Math.round(px * k))
  return { W, H, k, s, small: short < 360 }
}
export type Sizes = ReturnType<typeof sizesOf>

export const clamp = (value: number, low: number, high: number) => Math.max(low, Math.min(high, value))

// ---------------------------------------------------------------- icons

// Icons in a 24x24 box, drawn in the text color: lines, except the FILLED ones.
const PATHS: Record<string, string> = {
  run: 'M13.5 5.5a2 2 0 1 0 0-4 2 2 0 0 0 0 4zM9.9 19.4l1-4.4 2.1 2V23h2v-7.5l-2.1-2 .6-3c1.3 1.5 3.3 2.5 5.5 2.5v-2c-1.9 0-3.5-1-4.3-2.4l-1-1.6c-.4-.6-1-1-1.7-1-.3 0-.5.1-.8.1L6 8.3V13h2V9.6l1.8-.7L8.2 17l-4.9-1-.4 2z',
  ride: 'M15.5 5.5a2 2 0 1 0 0-4 2 2 0 0 0 0 4zM5 12a5 5 0 1 0 0 10 5 5 0 0 0 0-10zm0 8.5a3.5 3.5 0 1 1 0-7 3.5 3.5 0 0 1 0 7zm5.8-10l2.4-2.4.8.8c1.3 1.3 3 2.1 5 2.1V9c-1.5 0-2.7-.6-3.6-1.5l-1.9-1.9c-.5-.4-1-.6-1.6-.6s-1.1.2-1.4.6L7.8 8.4c-.4.4-.6.9-.6 1.4 0 .6.2 1.1.6 1.4L11 14v5h2v-6.2zM19 12a5 5 0 1 0 0 10 5 5 0 0 0 0-10zm0 8.5a3.5 3.5 0 1 1 0-7 3.5 3.5 0 0 1 0 7z',
  swim: 'M22 21c-1.1 0-1.7-.4-2.2-.7-.4-.3-.6-.4-1.1-.4s-.7.1-1.1.4c-.5.3-1.1.7-2.2.7s-1.7-.4-2.2-.7c-.4-.3-.6-.4-1.1-.4s-.7.1-1.1.4c-.5.3-1.1.7-2.2.7s-1.7-.4-2.2-.7c-.4-.3-.6-.4-1.1-.4s-.7.1-1.1.4c-.5.3-1.1.7-2.2.7v-2c.5 0 .7-.1 1.1-.4.5-.3 1.1-.7 2.2-.7s1.7.4 2.2.7c.4.3.6.4 1.1.4s.7-.1 1.1-.4c.5-.3 1.1-.7 2.2-.7s1.7.4 2.2.7c.4.3.6.4 1.1.4s.7-.1 1.1-.4c.5-.3 1.1-.7 2.2-.7s1.7.4 2.2.7c.4.3.6.4 1.1.4zm-13.5-5c.5 0 .7-.1 1.1-.4.5-.3 1.1-.7 2.2-.7s1.7.4 2.2.7c.4.3.6.4 1.1.4s.7-.1 1.1-.4c.3-.2.6-.4 1-.5L13.9 8c-.6-.6-1.4-1-2.3-1H8v2h3.6l1.2 1.2L9 14c.3-.1.6-.1 1-.1zM16.5 5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5z',
  refresh: 'M21 12a9 9 0 1 1-2.6-6.4L21 8M21 3v5h-5',
  alert: 'M12 3l10 18H2zM12 10v4M12 17v.01',
  key: 'M15 7a4 4 0 1 0-3.9 4.9L4 19v2h3v-2h2v-2h2l1.1-1.1A4 4 0 0 0 15 7zM15.5 7.5h.01',
  link: 'M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7',
  up: 'M2 20l7-11 4 5 3-4 6 10z',
  clock: 'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zM12 7v5l3 2',
  check: 'M5 12l5 5L20 7',
}
const FILLED: Record<string, boolean> = { run: true, ride: true, swim: true, up: true }

export const Icon = ({ name, size, width }: { name: string; size: number; width?: number }) => {
  const filled = FILLED[name]
  return (
    <svg className={`w-[${size}px] h-[${size}px] shrink-0`} viewBox="0 0 24 24"
      fill={filled ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth={filled ? 0 : width || 2}
      strokeLinecap="round" strokeLinejoin="round">
      <path d={PATHS[name] || PATHS.run} />
    </svg>
  )
}

// ---------------------------------------------------------------- parts

export function Banner({ t, z, text, onClose }: { t: Theme; z: Sizes; text: string; onClose?: () => void }) {
  return (
    <div className={`flex items-center shrink-0 gap-[${z.s(10)}px] rounded-[${z.s(12)}px] px-[${z.s(12)}px] py-[${z.s(8)}px] ${t.banner}`}
      onClick={onClose}>
      <Icon name="alert" size={z.s(20)} />
      <span className={`flex-1 text-[${z.s(14)}px] line-clamp-3`}>{text}</span>
    </div>
  )
}

// A screen that says what to do, step by step, with a button at the bottom.
// `tight`: a short screen (a 4.2" e-paper, a 2.8" LCD), where the header,
// the steps and the note scroll as one column; a short and wide one (a 5.79"
// strip) puts the steps side by side. `round`: a round panel's whole canvas,
// where the title sits in the arc at the top, the steps scroll in the middle
// of the circle with the note after them, and the button stays in the arc at
// the bottom.
export type Step = { head: string; text: string; code?: string }
export function SetupScreen({ t, z, icon, title, intro, steps, problem, action, note, tight, round }: {
  t: Theme; z: Sizes; icon: string; title: string; intro: string; steps: Step[]; problem?: string; action?: any; note?: string
  tight?: boolean; round?: { W: number; H: number }
}) {
  const g = (px: number) => z.s(tight ? px * 0.55 : px)
  const side = !!tight && !round && z.W >= z.H * 2.4
  const f = (px: number, least: number) => Math.max(Math.round(least * (side ? 1.2 : 1)), z.s(px))
  const list = (
    <div className={`flex ${side ? 'flex-row' : 'flex-col'} gap-[${g(10)}px]`}>
      {steps.map((step, index) => (
        <div className={`flex ${side ? 'flex-1 min-w-0' : ''} gap-[${z.s(12)}px] rounded-[${z.s(14)}px] px-[${z.s(12)}px] py-[${g(10)}px] ${t.card}`}>
          <div className={`w-[${f(30, 20)}px] h-[${f(30, 20)}px] shrink-0 rounded-full flex items-center justify-center text-[${f(16, 12)}px] font-bold ${t.step}`}>
            {index + 1}
          </div>
          <div className={`flex-1 min-w-0 flex flex-col gap-[${tight ? 1 : 4}px]`}>
            <span className={`text-[${f(17, 12)}px] font-bold`}>{step.head}</span>
            <span className={`text-[${f(14, 10)}px] ${t.muted}`}>{step.text}</span>
            {step.code ? (
              <span className={`self-start rounded-[8px] px-[${z.s(8)}px] ${tight ? '' : 'py-[2px] '}font-mono text-[${f(13, 10)}px] ${t.code}`}>{step.code}</span>
            ) : null}
          </div>
        </div>
      ))}
    </div>
  )
  if (round) {
    const { W, H } = round
    const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12
    const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
    const iconTop = Math.round(R * 0.93)
    const iconSize = z.s(38)
    const titleTop = iconTop - iconSize - z.s(4)
    const titleH = Math.round(z.s(22) * 1.3)
    const boxTop = titleTop - titleH - z.s(8)
    const actionH = action ? z.s(52) : 0
    const boxBottom = action ? Math.round(R * 0.38) : Math.round(R * 0.7)
    const boxW = Math.min(chord(boxTop), chord(boxBottom))
    const titleW = chord(titleTop)
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-[${Math.round(cx - iconSize / 2)}px] top-[${Math.round(cy - iconTop)}px] w-[${iconSize}px] h-[${iconSize}px] rounded-full flex items-center justify-center ${t.step}`}>
          <Icon name={icon} size={z.s(21)} />
        </div>
        <div className={`absolute left-[${Math.round(cx - titleW / 2)}px] top-[${Math.round(cy - titleTop)}px] w-[${titleW}px] flex justify-center`}>
          <span className={`text-[${z.s(22)}px] font-bold leading-tight truncate`}>{title}</span>
        </div>
        <div className={`absolute left-[${Math.round(cx - boxW / 2)}px] top-[${Math.round(cy - boxTop)}px] w-[${boxW}px] h-[${boxTop + boxBottom}px] overflow-y-auto`}>
          <div className={`flex flex-col gap-[${z.s(10)}px]`}>
            {problem ? <Banner t={t} z={z} text={problem} /> : <span className={`text-[${z.s(15)}px] text-center ${t.muted}`}>{intro}</span>}
            {list}
            {note ? <span className={`text-[${z.s(13)}px] text-center ${t.muted}`}>{note}</span> : null}
          </div>
        </div>
        {action ? (
          <div className={`absolute left-[${Math.round(cx - chord(boxBottom + z.s(8) + actionH) / 2)}px] top-[${Math.round(cy + boxBottom + z.s(8))}px] w-[${chord(boxBottom + z.s(8) + actionH)}px] h-[${actionH}px] flex justify-center`}>
            {action}
          </div>
        ) : null}
      </div>
    )
  }
  const header = (
    <div className={`flex items-center gap-[${z.s(12)}px]`}>
      <div className={`w-[${f(48, 28)}px] h-[${f(48, 28)}px] shrink-0 rounded-full flex items-center justify-center ${t.step}`}>
        <Icon name={icon} size={f(26, 16)} />
      </div>
      <div className="flex-1 min-w-0 flex flex-col">
        <span className={`text-[${f(26, 17)}px] font-bold leading-tight`}>{title}</span>
        {problem ? null : <span className={`text-[${f(15, 11)}px] ${t.muted}`}>{intro}</span>}
      </div>
    </div>
  )
  const noteLine = note ? <span className={`text-[${f(13, 10)}px] ${t.muted}`}>{note}</span> : null
  if (tight && !side)
    return (
      <div className={`flex flex-col w-full h-full gap-[${g(12)}px] p-[${g(20)}px] ${t.page}`}>
        <div className="flex-1 min-h-0 overflow-y-auto">
          <div className={`flex flex-col gap-[${g(12)}px]`}>
            {header}
            {problem ? <Banner t={t} z={z} text={problem} /> : null}
            {list}
            {noteLine}
          </div>
        </div>
        {action || null}
      </div>
    )
  return (
    <div className={`flex flex-col w-full h-full gap-[${g(12)}px] p-[${g(20)}px] ${t.page}`}>
      {header}
      {problem ? <Banner t={t} z={z} text={problem} /> : null}
      <div className="flex-1 min-h-0 overflow-y-auto">{list}</div>
      {action || null}
      {noteLine}
    </div>
  )
}

// The big button of a setup screen: a link (a QR code on the frame, a tab in
// the preview) or a tap.
export function BigButton({ t, z, icon, label, href, onClick }: {
  t: Theme; z: Sizes; icon: string; label: string; href?: string; onClick?: () => void
}) {
  const look = `self-center flex items-center gap-[${z.s(10)}px] h-[${z.s(52)}px] px-[${z.s(28)}px] rounded-full text-[${z.s(19)}px] font-bold ${t.primary}`
  const inside = [<Icon name={icon} size={z.s(22)} />, <span>{label}</span>]
  return href ? <a href={href} className={look}>{inside}</a> : <div className={look} onClick={onClick}>{inside}</div>
}
